class LruCache<K, V> extends LinkedHashMap<K, V> {
    private final int capacity;

    LruCache(int capacity) {
        super(capacity, 0.75f, true);   // true = access order
        this.capacity = capacity;
    }

    @Override
    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > capacity;
    }
}

LruCache<String, Integer> prices = new LruCache<>(2);
prices.put("Danube View", 80);
prices.put("Alpen Hof", 95);
prices.get("Danube View");          // now the most recent
prices.put("City Inn", 60);         // evicts Alpen Hof
System.out.println(prices.keySet());

final class RoomKey {
    private final int hotelId;
    private final int roomNumber;

    RoomKey(int hotelId, int roomNumber) {
        this.hotelId = hotelId;
        this.roomNumber = roomNumber;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) return true;
        if (!(other instanceof RoomKey)) return false;
        RoomKey that = (RoomKey) other;
        return hotelId == that.hotelId && roomNumber == that.roomNumber;
    }

    @Override
    public int hashCode() {
        // Same fields as equals, same order.
        return Objects.hash(hotelId, roomNumber);
    }
}

